const resumeTitleDefaults={summaryTitle:'PROFILE',educationTitle:'EDUCATION',experienceTitle:'INTERNSHIP EXPERIENCES',projectsTitle:'SELECTED PROJECTS',activitiesTitle:'EXTRACURRICULAR ACTIVITIES',awardsTitle:'HONORS & AWARDS',skillsTitle:'SKILLS'};
const resumeTrackLabels={'resume-us-spatial':'Spatial / Experience','resume-us-arch':'Architecture / Visualization','resume-cn-game':'Game / Creative'};
function legacyResumeSections(r){return [['summary','PROFILE'],['education','EDUCATION'],['experience','INTERNSHIP EXPERIENCES'],['projects','SELECTED PROJECTS'],['activities','EXTRACURRICULAR ACTIVITIES'],['awards','HONORS & AWARDS'],['skills','SKILLS']].map(([key,fallback])=>({id:`section-${key}`,title:r[`${key}Title`]??fallback,content:r[key]||''})).filter(s=>s.content.trim()||['section-education','section-experience','section-projects','section-skills'].includes(s.id))}
function normalizeResumes(resumes){return (resumes||structuredClone(initialData.resumes)).map(r=>{let merged={...resumeTitleDefaults,...r,track:resumeTrackLabels[r.id]||r.track,activities:r.activities||'',awards:r.awards||''};return {...merged,sections:Array.isArray(r.sections)?r.sections.map(s=>({id:s.id||uid(),title:String(s.title||''),content:String(s.content||'')})):legacyResumeSections(merged)}})}
