function searchSourceCard(s){return `<div class="card source-card"><span class="source-logo ${s[4]}">${s[1]}</span><div><h3>${s[2]}</h3><p>${s[3]}</p></div><button class="primary" data-action="open-search" data-platform="${s[0]}">打开官网 ↗</button></div>`}
function searchHubView(){return `<div class="card search-hero"><div><span class="tag us">官方渠道导航</span><h2>招聘与行业资源中心</h2><p class="subtle">输入关键词和城市，再打开需要的平台。登录与搜索发生在各平台官网，Career Atlas 不读取账号，也不保存密码。</p></div><div class="search-form"><div class="field"><label>岗位 / 技能 / 公司关键词</label><input id="onlineQuery" value="Spatial Designer" placeholder="例如 Spatial Designer / Unreal / 场景设计"></div><div class="field"><label>城市（支持的平台会自动带入）</label><input id="onlineLocation" value="Los Angeles" placeholder="例如 Los Angeles / 上海"></div></div></div>${searchSourceGroups.map(g=>`<section class="search-section"><div class="search-section-head"><div><h2>${g.title}</h2><p>${g.note}</p></div><span>${g.sources.length} 个渠道</span></div><div class="grid search-grid">${g.sources.map(searchSourceCard).join('')}</div></section>`).join('')}<div class="card search-note"><b>使用建议</b><span>综合平台负责发现机会，垂直平台负责提高匹配度，公司官网负责最终核实。不要在任何平台向陌生人提供验证码或付款。</span></div><div class="card capture-card"><div><h2>找到结果后快速保存</h2><p class="subtle">把官网留在浏览器中，回到这里记录关键内容，避免重复搜索。</p></div><div><button class="secondary" data-action="add-contact">＋ 保存联系人</button> <button class="primary" data-action="add-job">＋ 保存岗位</button></div></div>`}
function openOnlineSearch(platform){let q=encodeURIComponent(document.getElementById('onlineQuery')?.value.trim()||''),loc=encodeURIComponent(document.getElementById('onlineLocation')?.value.trim()||'');let urls={
  'linkedin-jobs':`https://www.linkedin.com/jobs/search/?keywords=${q}&location=${loc}`,
  'linkedin-people':`https://www.linkedin.com/search/results/people/?keywords=${q}`,
  'indeed':`https://www.indeed.com/jobs?q=${q}&l=${loc}`,
  'glassdoor':`https://www.glassdoor.com/Job/jobs.htm?sc.keyword=${q}&locKeyword=${loc}`,
  'builtin':`https://builtin.com/jobs?search=${q}`,
  'wellfound':'https://wellfound.com/jobs',
  'handshake':`https://app.joinhandshake.com/stu/postings?query=${q}`,
  '12twenty':'https://ucla.12twenty.com/',
  'archinect':'https://archinect.com/jobs',
  'aia':'https://careercenter.aia.org/jobs/',
  'dezeen':'https://www.dezeenjobs.com/',
  'coroflot':'https://www.coroflot.com/design-jobs',
  'hitmarker':`https://hitmarker.net/jobs?search=${q}`,
  'artstation':'https://www.artstation.com/jobs',
  'zhipin':`https://www.zhipin.com/web/geek/job?query=${q}`,
  'liepin':`https://www.liepin.com/zhaopin/?key=${q}`,
  'zhaopin':`https://sou.zhaopin.com/?kw=${q}`,
  '51job':`https://we.51job.com/pc/search?keyword=${q}`,
  'lagou':`https://www.lagou.com/wn/jobs?kd=${q}`,
  'nowcoder':'https://www.nowcoder.com/jobs/school',
  'maimai':'https://maimai.cn/'
};let url=urls[platform];if(!url)return toast('这个渠道暂时不可用');if(window.careerAtlas)window.careerAtlas.openExternal(url).catch(()=>toast('无法打开网页，请检查默认浏览器'));else window.open(url,'_blank')}
function jobsView(){return trackerView('jobs','搜索公司或岗位…','添加岗位','job')}
function networkView(){return trackerView('contacts','搜索姓名或公司…','添加联系人','contact')}
function trackerView(type,placeholder,addLabel,entity){let rows=data[type];return `<div class="toolbar"><input id="search" placeholder="${placeholder}"><select id="trackFilter"><option value="">全部</option>${type==='jobs'?['美国','中国'].map(x=>`<option>${x}</option>`).join(''):['待联系','已联系','保持联系'].map(x=>`<option>${x}</option>`).join('')}</select><button class="secondary" data-action="export" data-type="${type}">⇩ 导出 CSV</button><button class="primary" data-action="add-${entity}">＋ ${addLabel}</button></div><div class="card table-card"><table><thead><tr>${columns[type].map(c=>`<th>${c[1]}</th>`).join('')}<th></th></tr></thead><tbody id="trackerBody">${trackerRows(type,rows)}</tbody></table></div>`}
function trackerRows(type,rows){if(!rows.length)return `<tr><td colspan="9">${empty('还没有记录')}</td></tr>`;return rows.map(r=>`<tr>${columns[type].map(([key])=>{let value=key==='place'?`${r.country} · ${r.city}`:r[key];return `<td>${key==='status'?`<span class="status ${esc(value)}">${esc(value)}</span>`:esc(value||'—')}</td>`}).join('')}<td class="row-actions"><button data-action="edit-${type==='jobs'?'job':'contact'}" data-id="${r.id}">✎</button><button data-action="delete-${type==='jobs'?'job':'contact'}" data-id="${r.id}">×</button></td></tr>`).join('')}
function portfolioView(){return `<div class="toolbar"><span class="subtle">把建筑训练转化为空间叙事、实时 3D 与视觉设计能力。</span><button class="secondary" data-action="export" data-type="projects">⇩ 导出 CSV</button><button class="primary" data-action="add-project">＋ 添加项目</button></div><div class="grid portfolio-grid">${data.projects.map(p=>`<div class="card project-card"><div class="project-top"><span class="tag ${p.track==='美国'?'us':p.track==='中国'?'cn':'both'}">${esc(p.track)}</span><span class="row-actions"><button data-action="edit-project" data-id="${p.id}">✎</button><button data-action="delete-project" data-id="${p.id}">×</button></span></div><h3>${esc(p.name)}</h3><span class="subtle">${esc(p.type)} · ${esc(p.deadline)}</span><p>下一步：${esc(p.next)}</p><div class="project-progress"><span>Progress</span><b>${p.progress}%</b></div><div class="bar"><span style="width:${p.progress}%"></span></div></div>`).join('')||empty('还没有作品集项目')}</div>`}
function timelineView(){let milestones=[['2026.08.22 — 09.30','Stage 1 · Restart & Foundation',['前 7 天恢复节奏：每天只做一个 30–90 分钟核心任务','CV、LinkedIn、GitHub 与 Portfolio V0.5 建立基础','建立目标公司清单并完成第一批真实申请']],['2026.10.01 — 11.15','Stage 2 · Portfolio Ready',['Hero Environment 推进至 60–100%','核心仓库 README 讲清问题、过程、贡献、工具与结果','Portfolio V1 可支持定向申请']],['2026.11.16 — 2027.03','Stage 3 · Market Ready',['Applications + Networking 稳定加速','每月维护 GitHub 置顶项目和个人主页一致性','Apply → Interview → Improve → Apply']],['2027.04 — 05','Stage 4 · Interview',['测试题、面试与 follow-up 优先','用 GitHub / Portfolio 提供可验证的项目证据','比较职责、成长、签证、团队与城市成本']],['2027.06','Offer 决策与入职',['综合比较岗位内容、成长、团队、地点、签证与作品积累','确认 OPT、岗位相关性及入职材料']]];let stage=currentStage();return `<div class="card timeline">${milestones.map((m,i)=>`<div class="milestone ${careerStages[i]?.id===stage.id?'active':''}"><span class="tag">${m[0]}</span><h3 style="margin-top:10px">${m[1]}</h3><ul>${m[2].map(x=>`<li>${x}</li>`).join('')}</ul></div>`).join('')}</div>`}
function strategyView(){let stage=currentStage();return `<div class="stage-banner"><div><span class="tag both">${stage.name}</span><h2>${stage.focus}</h2><p>职业结果由定位、作品证据、市场行动、关系网络和公开专业形象共同决定。</p></div></div><div class="grid strategy-grid"><div class="card strategy-panel us-panel"><span class="tag us">职业定位与市场组合</span><h2>形成统一但不单一的职业身份</h2><p class="subtle">用 Architecture-trained Spatial / Environment Designer 串联空间、3D、实时与视觉化能力。</p><ul><li>核心岗位：Spatial / Experiential / Real-time / Visualization</li><li>Architecture + Visualization 保持教育与工作授权叙事连续</li><li>Game Environment / Worldbuilding 作为作品驱动的拓展方向</li><li>按真实截止日期、匹配度、成长空间、地点与签证风险排序</li></ul></div><div class="card strategy-panel cn-panel"><span class="tag cn">作品与市场反馈</span><h2>用可判断的作品进入真实市场</h2><p class="subtle">不等待“完美作品集”，先让材料可读，再根据岗位、测试和面试反馈迭代。</p><ul><li>每个项目清楚说明问题、个人角色、过程、工具与结果</li><li>维护针对不同岗位的简历版本和作品顺序</li><li>记录申请限制、作品要求、截止日期和反馈</li><li>每月检查申请→回复→面试转化率，定位真正瓶颈</li></ul></div><div class="card strategy-panel github-panel"><span class="tag">PUBLIC PROOF</span><h2>把 GitHub 建成专业证据库</h2><p class="subtle">目标不是刷提交次数，而是让招聘方快速理解你如何工作、如何组织复杂项目。</p><ul><li>主页简介只保留职业定位、核心工具、Portfolio 与 LinkedIn</li><li>置顶 3–4 个最相关仓库：Career Atlas、AI/设计研究、技术或实时项目</li><li>每个 README 包含项目目的、个人贡献、流程图/截图、技术栈、运行方法和结果</li><li>不上传 API Key、个人简历数据、未授权公司文件或课程受限材料</li><li>每月一次整理即可，避免 GitHub 挤占作品集和申请时间</li></ul></div><div class="card strategy-panel network-panel"><span class="tag">RELATIONSHIPS & SIGNAL</span><h2>让材料、表达和关系互相增强</h2><p class="subtle">LinkedIn、GitHub、Portfolio、简历和面试叙事应使用一致的职业语言。</p><ul><li>Networking 以校友、目标团队从业者和真实反馈为主</li><li>为 30 秒、5 分钟、15 分钟准备同一套项目叙事</li><li>保留健康、课程和深度创作时间，避免数量型焦虑</li><li>书面 Offer 前保持合理申请管线，并定期备份数据</li></ul></div></div><div class="card priority-logic"><h2>动态排序模型</h2><div class="logic-flow"><span>1 · Deadline</span><b>→</b><span>2 · Readiness</span><b>→</b><span>3 · Opportunity Value</span><b>→</b><span>4 · Career Fit</span><b>→</b><span>5 · Effort</span></div></div>`}
function empty(s){return `<div class="empty">${s}</div>`}
function bindView(){document.getElementById('content').onclick=async e=>{let b=e.target.closest('[data-action]');if(!b)return;let a=b.dataset.action,id=b.dataset.id;if(a==='toggle-task'){let t=data.tasks.find(x=>x.id===id);t.done=!t.done;save()}else if(a==='open-search')openOnlineSearch(b.dataset.platform);else if(a==='select-resume'){selectedResumeId=id;render()}else if(a==='resume-version-add')addResumeVersion();else if(a==='resume-version-rename')renameResumeVersion(id);else if(a==='resume-version-copy')copyResumeVersion(id);else if(a==='resume-version-delete')deleteResumeVersion(id);else if(a==='resume-add-section')addResumeSection();else if(a==='resume-section-up')moveResumeSection(id,-1);else if(a==='resume-section-down')moveResumeSection(id,1);else if(a==='resume-section-delete')deleteResumeSection(id);else if(a==='resume-word'){let r=await window.careerAtlas.exportResumeWord(currentResume());if(!r.canceled)toast('Word 简历已导出')}else if(a==='resume-pdf'){let r=await window.careerAtlas.exportResumePdf(currentResume());if(!r.canceled)toast('PDF 简历已导出')}else if(a.startsWith('add-'))openModal(a.slice(4));else if(a.startsWith('edit-'))openModal(a.slice(5),id);else if(a.startsWith('delete-'))remove(a.slice(7),id);else if(a==='edit-kpi')openModal('kpi');else if(a==='export')exportCsv(b.dataset.type)};let search=document.getElementById('search'),filter=document.getElementById('trackFilter');if(search){let run=()=>{let type=currentView==='jobs'?'jobs':'contacts',q=search.value.toLowerCase(),f=filter.value;let rows=data[type].filter(r=>Object.values(r).join(' ').toLowerCase().includes(q)&&(type==='jobs'?(!f||r.country===f):(!f||r.status===f)));document.getElementById('trackerBody').innerHTML=trackerRows(type,rows)};search.oninput=run;filter.onchange=run}let tf=document.getElementById('taskFilter'),df=document.getElementById('dateFilter');if(tf&&df){let labels={today:['每日任务','今天具体要完成的行动'],week:['未来 7 天','查看接下来一周的具体安排'],all:['所有任务','查看完整求职计划']},run=()=>{let rows=visibleTasks(df.value,tf.value),copy=labels[df.value];document.getElementById('allTasks').innerHTML=rows.map(taskHtml).join('')||empty('这个筛选范围还没有任务');document.getElementById('taskCount').textContent=`${rows.filter(t=>t.done).length} / ${rows.length} 完成`;document.getElementById('taskListTitle').textContent=copy[0];document.getElementById('taskListHint').textContent=copy[1]};tf.onchange=run;df.onchange=run}}
function remove(type,id){let map={task:'tasks',job:'jobs',contact:'contacts',project:'projects'},key=map[type];if(confirm('确定删除这条记录？')){data[key]=data[key].filter(x=>x.id!==id);save();toast('已删除')}}
const forms={
 task:{title:'任务',key:'tasks',fields:[['title','任务名称','text'],['category','类别','select',['Portfolio','Applications','Networking','Skill','Planning']],['date','截止 / 执行日期','date'],['opportunity','机会价值','select',['High','Medium','Low']],['readiness','准备度','select',['Ready','Partial','Blocked']],['effort','预计分钟','number'],['note','说明','textarea']]},
 job:{title:'岗位',key:'jobs',fields:[['company','公司','text'],['role','岗位','text'],['country','国家','select',['美国','中国']],['city','城市','text'],['direction','方向','select',['Experiential','Spatial / 3D','Game','Architecture','Visualization','AI / Creative']],['status','状态','select',['关注','准备申请','已申请','面试中','Offer','拒绝']],['date','投递日期','date'],['contact','联系人','text'],['salary','薪资','text'],['notes','备注','textarea']]},
 contact:{title:'联系人',key:'contacts',fields:[['name','姓名','text'],['company','公司','text'],['role','职位','text'],['country','国家','select',['美国','中国']],['channel','渠道','select',['LinkedIn','Email','微信','校友活动','其他']],['status','状态','select',['待联系','已联系','保持联系']],['lastDate','最近联系','date'],['next','下一步','text'],['notes','备注','textarea']]},
 project:{title:'作品集项目',key:'projects',fields:[['name','项目名称','text'],['type','类型 / 方向','text'],['track','轨道','select',['美国','中国','美国/中国']],['progress','进度 %','number'],['deadline','目标日期','date'],['next','下一步行动','text'],['notes','备注','textarea']]}
};
function openModal(type,id){if(type==='kpi')return kpiModal();let f=forms[type]||forms.task,item=id?data[f.key].find(x=>x.id===id):{};document.getElementById('modalRoot').innerHTML=`<div class="modal-backdrop"><form class="modal" id="editForm"><div class="modal-head"><div><p class="eyebrow">${id?'EDIT':'NEW'}</p><h2>${id?'编辑':'添加'}${f.title}</h2></div><button class="close" type="button">×</button></div><div class="form-grid">${f.fields.map(([key,label,input,opts])=>fieldHtml(key,label,input,opts,item[key])).join('')}</div><div class="modal-actions"><button class="secondary close" type="button">取消</button><button class="primary" type="submit">保存</button></div></form></div>`;wireModal(form=>{let obj={...item,id:item.id||uid()};f.fields.forEach(([key,,input])=>obj[key]=input==='number'?Number(form.elements[key].value):form.elements[key].value);if(!id&&type==='task')obj.done=false;if(id)data[f.key]=data[f.key].map(x=>x.id===id?obj:x);else data[f.key].unshift(obj);save();toast('已保存')})}
function fieldHtml(key,label,type,opts,val=''){let full=type==='textarea'?' full':'';let control=type==='select'?`<select name="${key}">${opts.map(o=>`<option ${o===val?'selected':''}>${o}</option>`).join('')}</select>`:type==='textarea'?`<textarea name="${key}">${esc(val)}</textarea>`:`<input name="${key}" type="${type}" value="${esc(val)}" ${key==='progress'?'min="0" max="100"':''}>`;return `<div class="field${full}"><label>${label}</label>${control}</div>`}
function kpiModal(){let k=data.kpi;document.getElementById('modalRoot').innerHTML=`<div class="modal-backdrop"><form class="modal" id="editForm"><div class="modal-head"><div><p class="eyebrow">WEEKLY CHECK-IN</p><h2>更新本周 KPI</h2></div><button class="close" type="button">×</button></div><div class="form-grid">${[['portfolio','Portfolio hours'],['applications','Applications'],['networking','Networking'],['skill','Skill hours']].map(([key,l])=>fieldHtml(key,l,'number',null,k[key])).join('')}</div><div class="modal-actions"><button class="secondary close" type="button">取消</button><button class="primary">保存</button></div></form></div>`;wireModal(form=>{['portfolio','applications','networking','skill'].forEach(x=>data.kpi[x]=Number(form.elements[x].value));save();toast('本周进度已更新')})}
function wireModal(onSubmit){let root=document.getElementById('modalRoot');root.querySelectorAll('.close').forEach(b=>b.onclick=()=>root.innerHTML='');root.querySelector('.modal-backdrop').onclick=e=>{if(e.target.classList.contains('modal-backdrop'))root.innerHTML=''};root.querySelector('form').onsubmit=e=>{e.preventDefault();onSubmit(e.target);root.innerHTML=''}}
function exportCsv(type){let rows=data[type],cols=type==='jobs'?['company','role','country','city','direction','status','date','contact','salary','notes']:type==='contacts'?['name','company','role','country','channel','status','lastDate','next','notes']:['name','type','track','progress','deadline','next','notes'];let csv=[cols.join(','),...rows.map(r=>cols.map(c=>`"${String(r[c]??'').replace(/"/g,'""')}"`).join(','))].join('\r\n');let names={jobs:'Career-Atlas-Jobs.csv',contacts:'Career-Atlas-Networking.csv',projects:'Career-Atlas-Portfolio.csv'};if(window.careerAtlas)window.careerAtlas.exportCsv({filename:names[type],content:csv}).then(r=>!r.canceled&&toast('CSV 已导出'));else{let a=document.createElement('a');a.href=URL.createObjectURL(new Blob(['\uFEFF'+csv],{type:'text/csv'}));a.download=names[type];a.click();toast('CSV 已导出')}}
function toast(msg){let t=document.getElementById('toast');t.textContent=msg;t.classList.add('show');setTimeout(()=>t.classList.remove('show'),1800)}
init();
